"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "reports",
    "uid": "uid-deployment-reports"
  },
  "params": {
    "containers": {
      "renderer": {
        "limits": {
          "cpu": "1500m"
        }
      }
    }
  },
  "expected_effect": "Raise the CPU limit for the renderer container to 1.5 cores, preventing throttling and allowing it to meet its CPU demand without hitting the limit.",
  "rationale": "The current revision's renderer container is using 0.93 CPU (93% of its 1-core limit) with 41% throttling, while the previous revision had 0.39 throttling ratio. The image change in the rollout likely increased CPU usage, requiring a higher limit to avoid throttling.",
